water.implementation:
uniform shader inputImage;
uniform float2 pixelScale; // authored {1,1}; a point, so it arrives as the device scale
uniform float phase;
uniform float2 centre;
uniform float radius;
uniform float agitation;
uniform float2 lean;
uniform float2 charge;
uniform float4 deepColor;
uniform float4 skinColor;
uniform float4 sparkColor;
uniform float wobble;

float hash21(float2 p) {
  p = fract(p * float2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float valueNoise(float2 p) {
  float2 cell = floor(p);
  float2 f = fract(p);
  float2 w = f * f * (3.0 - 2.0 * f);
  float a = hash21(cell);
  float b = hash21(cell + float2(1.0, 0.0));
  float c = hash21(cell + float2(0.0, 1.0));
  float d = hash21(cell + float2(1.0, 1.0));
  return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// Three octaves is enough for water and keeps the CPU interpreter honest.
float fbm(float2 p) {
  float total = 0.0;
  float amplitude = 0.5;
  for (int i = 0; i < 3; i++) {
    total += amplitude * valueNoise(p);
    p = p * 2.07 + float2(19.3, 7.7);
    amplitude *= 0.5;
  }
  return total;
}

half4 main(float2 device) {
  // Everything below is in composition units. `device`, `centre`, `lean` and
  // `charge` arrive in device pixels; dividing them by the device scale is
  // what keeps the arcs and glow the same size relative to the body at any
  // render size, instead of shrinking into it as the scale grows.
  float scale = max(pixelScale.x, 0.0001);
  float2 p = device / scale - lean / scale;
  float2 centreC = centre / scale;
  float2 chargeC = charge / scale;
  float2 rel = p - centreC;
  float len = length(rel);
  float2 dir = len > 0.001 ? rel / len : float2(0.0, -1.0);
  float angle = atan(rel.y, rel.x);

  // --- 1. Surface tension -------------------------------------------------
  // The mask is a circle. Everything blobby about the silhouette is this:
  // sampling the mask at a radially displaced point pushes the edge in and out.
  float gain = wobble * (1.0 + 0.85 * agitation);
  float lobes =
      sin(3.0 * angle + 1.0 * phase) * 0.58
    + sin(5.0 * angle - 2.0 * phase) * 0.26
    + sin(2.0 * angle + 3.0 * phase) * 0.24;
  float breath = sin(2.0 * phase) * 0.34 + sin(3.0 * phase + 1.1) * 0.18;
  float2 slosh = float2(sin(phase) * 0.12, cos(2.0 * phase) * 0.09) * gain;
  float2 sampleP = p - dir * (lobes + breath) * gain - slosh;
  half4 source = inputImage.eval(sampleP * scale + lean);
  float bodyAlpha = float(source.a);

  // Material space: measured from the mask centre at the point actually shown,
  // so the silhouette sits at exactly m = 1 whatever the wobble is doing.
  float2 relM = sampleP - centreC;
  float m = length(relM) / max(radius, 1.0);
  float2 q = relM / max(radius, 1.0);

  // --- 2. Caustics --------------------------------------------------------
  // Two advected noise fields, the second warped by the first, then ridged.
  // The advection travels a closed circle in phase, so it never seams.
  float2 drift = float2(cos(phase), sin(phase));
  float base1 = fbm(q * 3.1 + drift * 0.85);
  float base2 = fbm(q * 6.3 - drift * 0.55 + base1 * 1.4 + float2(sin(2.0 * phase) * 0.4, 0.0));
  float ridged = 1.0 - abs(base2 * 2.0 - 1.0);
  float caustic = pow(clamp(ridged, 0.0, 1.0), 4.0);
  // Light pools low in a droplet rather than spreading evenly.
  float pool = smoothstep(-0.9, 0.75, q.y) * 0.7 + 0.35;

  // --- 3. Body ------------------------------------------------------------
  float depth = clamp(1.0 - m, 0.0, 1.0);
  float3 body = mix(deepColor.rgb, skinColor.rgb, smoothstep(0.0, 0.80, depth * depth));
  float key = clamp(dot(normalize(relM + float2(0.001)), float2(-0.55, -0.83)), 0.0, 1.0);
  body += skinColor.rgb * pow(key, 2.0) * 0.34 * depth;
  body += sparkColor.rgb * caustic * pool * (0.36 + 0.50 * agitation);
  // The meniscus: a thin bright band right at the surface, not a wide fade.
  float meniscus = smoothstep(0.80, 0.99, m) * (1.0 - smoothstep(0.99, 1.06, m));
  body += sparkColor.rgb * meniscus * 0.70;
  // A little of the sky picked up along the top edge.
  body += skinColor.rgb * smoothstep(0.55, 1.0, m) * clamp(-q.y, 0.0, 1.0) * 0.28;

  // --- 4. Electricity -----------------------------------------------------
  // A filament is the zero crossing of a drifting noise field: thin, branching,
  // and it moves without any of it ever being drawn twice. A bright core plus a
  // wide soft bloom is what separates lightning from a scratch.
  float2 charged = chargeC - centreC;
  float2 chargeDir = length(charged) > 0.001 ? normalize(charged) : float2(0.0, -1.0);
  float facing = clamp(dot(dir, chargeDir) * 0.5 + 0.5, 0.0, 1.0);

  float field = fbm(q * 2.8 + float2(cos(2.0 * phase), sin(2.0 * phase)) * 1.25);
  float branchField = fbm(q * 5.4 - float2(sin(3.0 * phase), cos(3.0 * phase)) * 0.85 + 11.0);
  float coreWidth = 0.011 + 0.007 * agitation;
  float d1 = abs(field - 0.5);
  float core = 1.0 - smoothstep(0.0, coreWidth, d1);
  float bloom = 1.0 - smoothstep(0.0, coreWidth * 9.0, d1);
  float branch = 1.0 - smoothstep(0.0, coreWidth * 0.85, abs(branchField - 0.5));

  // Arcs run across the body but crowd the surface, and leap a little past it.
  float shell = (0.30 + 0.70 * smoothstep(0.12, 0.88, m)) * (1.0 - smoothstep(0.99, 1.22, m));
  float flicker = 0.50 + 0.50 * sin(7.0 * phase + field * 14.0);
  // Presence decides *whether* a filament is lit, not how grey it is. Dimming
  // the core is what turns lightning into a smudge, so gate instead: below the
  // threshold there is nothing, above it the core is fully bright.
  float presence = shell * (0.52 + 0.80 * facing) * flicker * (0.62 + 1.05 * agitation);
  float visible = smoothstep(0.16, 0.44, presence);
  float bright = clamp(core + branch * 0.80, 0.0, 1.0) * visible;
  float halo = clamp(bloom * bloom * visible * 0.30, 0.0, 1.0);
  float3 arcColor = mix(sparkColor.rgb, float3(1.0), 0.6);
  float arcAlpha = clamp(bright + halo, 0.0, 1.0);
  float3 arcPremul = arcColor * bright + sparkColor.rgb * halo;

  // --- 5. Glow ------------------------------------------------------------
  float glow = (1.0 - smoothstep(0.98, 1.70, m)) * (0.11 + 0.24 * agitation);
  float glowAlpha = glow * clamp(1.0 - bodyAlpha, 0.0, 1.0);

  // --- 6. Composite (premultiplied) --------------------------------------
  float alpha = clamp(bodyAlpha + glowAlpha + arcAlpha, 0.0, 1.0);
  float3 premul = body * bodyAlpha + skinColor.rgb * glowAlpha * 0.9 + arcPremul;
  return half4(half3(clamp(premul, 0.0, alpha)), half(alpha));
}
